def comb_sort(nums):
    """Write a function to sort a list of elements using comb sort."""
    result = list(nums)
    length = len(result)
    gap = length
    shrink_factor = 1.3
    is_sorted = False

    while not is_sorted:
        gap = int(gap / shrink_factor)
        if gap <= 1:
            gap = 1
            is_sorted = True

        index = 0
        while index + gap < length:
            if result[index] > result[index + gap]:
                result[index], result[index + gap] = result[index + gap], result[index]
                is_sorted = False
            index += 1

    return result
